import { Inter } from 'next/font/google';
import Resume from './Resume';
import { pageMeta } from '../lib/meta';

// Only the resume sheet uses Inter, so it loads here (self-hosted by Next) rather
// than on every page
const inter = Inter({ subsets: ['latin'], weight: ['300', '400', '500', '600'], variable: '--font-inter' });

export const metadata = pageMeta({
  title: 'Resume',
  description: 'Resume of Abhi Velaga, senior frontend engineer.',
  // Generated by opengraph-image.js next to this file
  image: '/resume/opengraph-image',
  path: '/resume',
});

export default function ResumePage() {
  return <Resume fontClass={inter.variable} />;
}
